Evaluate the JavaScript sorting algorithms visualizer implementation. 

Solution A: (function initVisualizer(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    const maxVal = 100;
    const arraySize = 50;
    const barWidth = width / arraySize;

    // State
    const state = {
        array: [],
        comparisons: 0,
        swaps: 0,
        compareIndices: [],
        swapIndices: [],
        pivotIndex: null,
        sortedCount: 0,
        isRunning: false,
        algorithm: 'bubble',
        speed: 5,
        continuous: true,
        stack: [],
        delay: 200,
        stepResolve: null,
        maxStackDepth: 0
    };

    // UI Elements
    const container = document.createElement('div');
    container.style.display = 'flex';
    container.style.flexDirection = 'column';
    container.style.alignItems = 'flex-start';
    container.style.marginBottom = '10px';
    canvas.parentNode.insertBefore(container, canvas);

    const controls = document.createElement('div');
    controls.style.display = 'flex';
    controls.style.gap = '10px';
    container.appendChild(controls);

    const algorithmSelect = document.createElement('select');
    algorithmSelect.id = 'algSelect';
    ['Bubble Sort', 'Quick Sort', 'Merge Sort', 'Heap Sort', 'Radix Sort'].forEach((name, idx) => {
        const opt = document.createElement('option');
        opt.value = name.toLowerCase().replace(/ /g, '');
        opt.textContent = name;
        algorithmSelect.appendChild(opt);
    });
    controls.appendChild(algorithmSelect);

    const startButton = document.createElement('button');
    startButton.textContent = 'Start Sort';
    controls.appendChild(startButton);

    const speedLabel = document.createElement('label');
    speedLabel.textContent = 'Speed:';
    const speedSlider = document.createElement('input');
    speedSlider.type = 'range';
    speedSlider.min = '1';
    speedSlider.max = '10';
    speedSlider.value = state.speed;
    speedLabel.appendChild(speedSlider);
    controls.appendChild(speedLabel);

    const continuousLabel = document.createElement('label');
    const continuousCheckbox = document.createElement('input');
    continuousCheckbox.type = 'checkbox';
    continuousCheckbox.checked = state.continuous;
    continuousLabel.appendChild(continuousCheckbox);
    continuousLabel.appendChild(document.createTextNode('Continuous'));
    controls.appendChild(continuousLabel);

    const nextButton = document.createElement('button');
    nextButton.textContent = 'Next Step';
    nextButton.style.display = state.continuous ? 'none' : 'inline-block';
    controls.appendChild(nextButton);

    const scrambleContainer = document.createElement('div');
    scrambleContainer.style.display = 'flex';
    scrambleContainer.style.alignItems = 'center';
    scrambleContainer.style.gap = '5px';
    const scrambleSelect = document.createElement('select');
    ['Random', 'Reverse', 'Nearly Sorted'].forEach((opt) => {
        const option = document.createElement('option');
        option.value = opt.toLowerCase().replace(' ', '');
        option.textContent = opt;
        scrambleSelect.appendChild(option);
    });
    scrambleContainer.appendChild(scrambleSelect);
    const scrambleButton = document.createElement('button');
    scrambleButton.textContent = 'Scramble';
    scrambleContainer.appendChild(scrambleButton);
    controls.appendChild(scrambleContainer);

    const stats = document.createElement('div');
    stats.style.marginTop = '10px';
    stats.style.display = 'grid';
    stats.style.gridTemplateColumns = 'auto auto';
    stats.style.gap = '10px';
    container.appendChild(stats);

    const comparisonStat = document.createElement('div');
    const swapStat = document.createElement('div');
    const complexityStat = document.createElement('div');
    const stackDepthStat = document.createElement('div');
    stats.appendChild(comparisonStat);
    stats.appendChild(comparisonStat.cloneNode(true));
    stats.appendChild(comparisonStat.cloneNode(true));
    stats.appendChild(comparisonStat.cloneNode(true));
    const compText = document.createElement('span');
    compText.textContent = 'Comparisons: ';
    const compValue = document.createElement('span');
    compValue.textContent = '0';
    comparisonStat.appendChild(compText);
    comparisonStat.appendChild(compValue);

    const swapText = document.createElement('span');
    swapText.textContent = 'Swaps: ';
    const swapValue = document.createElement('span');
    swapValue.textContent = '0';
    swapStat.appendChild(swapText);
    swapStat.appendChild(swapValue);

    const complexityText = document.createElement('span');
    complexityText.textContent = 'Complexity: ';
    const complexityValue = document.createElement('span');
    complexityValue.textContent = 'O(n^2)';
    complexityStat.appendChild(complexityText);
    complexityStat.appendChild(complexityValue);

    const stackDepthText = document.createElement('span');
    stackDepthText.textContent = 'Stack Depth: ';
    const stackDepthValue = document.createElement('span');
    stackDepthValue.textContent = '0';
    stackDepthStat.appendChild(stackDepthText);
    stackDepthStat.appendChild(stackDepthValue);

    function updateStats() {
        compValue.textContent = state.comparisons;
        swapValue.textContent = state.swaps;
        stackDepthValue.textContent = state.stack.length;
    }

    function setComplexity() {
        const map = {
            bubblsort: 'O(n²)',
            quicksort: 'O(n log n)',
            mergesort: 'O(n log n)',
            heapsort: 'O(n log n)',
            radixsort: 'O(nk)'
        };
        complexityValue.textContent = map[state.algorithm] || 'O(n log n)';
    }

    function scrambleArray(pattern) {
        const arr = [];
        if (pattern === 'random') {
            for (let i = 0; i < arraySize; i++) arr.push(Math.floor(Math.random() * maxVal) + 1);
        } else if (pattern === 'reverse') {
            for (let i = arraySize; i > 0; i--) arr.push(i);
        } else if (pattern === 'nearlysorted') {
            for (let i = 1; i <= arraySize; i++) arr.push(i);
            const swaps = Math.max(1, Math.floor(arraySize * 0.05));
            for (let s = 0; s < swaps; s++) {
                const a = Math.floor(Math.random() * arraySize);
                const b = Math.floor(Math.random() * arraySize);
                [arr[a], arr[b]] = [arr[b], arr[a]];
            }
        }
        state.array = arr;
        state.sortedCount = 0;
        state.compareIndices = [];
        state.swapIndices = [];
        state.pivotIndex = null;
        state.comparisons = 0;
        state.swaps = 0;
        state.stack = [];
        state.maxStackDepth = 0;
        draw();
        updateStats();
    }

    function draw() {
        ctx.clearRect(0, 0, width, height);
        // Highlight working area
        if (state.stack.length > 0) {
            const top = state.stack[state.stack.length - 1];
            const l = top.l;
            const r = top.r;
            ctx.fillStyle = 'rgba(200,200,200,0.3)';
            ctx.fillRect(l * barWidth, 0, (r - l + 1) * barWidth, height);
        }
        // Draw bars
        state.array.forEach((val, idx) => {
            const barHeight = (val / maxVal) * height;
            let color = '#bbb';
            if (state.compareIndices.includes(idx)) color = 'red';
            if (state.swapIndices.includes(idx)) color = 'yellow';
            if (state.pivotIndex !== null && state.pivotIndex === idx) color = 'blue';
            if (idx < state.sortedCount) color = 'green';
            ctx.fillStyle = color;
            ctx.fillRect(idx * barWidth, height - barHeight, barWidth, barHeight);
        });
    }

    function delay(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    async function step() {
        if (state.continuous) {
            await delay(state.delay);
        } else {
            await new Promise(resolve => {
                state.stepResolve = resolve;
            });
            state.stepResolve = null;
        }
    }

    function swap(i, j) {
        [state.array[i], state.array[j]] = [state.array[j], state.array[i]];
        state.swaps++;
    }

    // Sorting algorithms
    async function bubbleSort() {
        const n = state.array.length;
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < n - i - 1; j++) {
                state.compareIndices = [j, j + 1];
                draw();
                await step();
                state.compareIndices = [];
                if (state.array[j] > state.array[j + 1]) {
                    state.swapIndices = [j, j + 1];
                    draw();
                    await step();
                    swap(j, j + 1);
                    state.swapIndices = [];
                    draw();
                    await step();
                }
            }
            state.sortedCount = i + 1;
            draw();
            updateStats();
        }
        state.sortedCount = n;
        draw();
    }

    async function quickSort(l = 0, r = state.array.length - 1) {
        state.stack.push({ l, r, type: 'quick' });
        if (l < r) {
            const pi = await partition(l, r);
            await quickSort(l, pi - 1);
            await quickSort(pi + 1, r);
        }
        state.stack.pop();
    }

    async function partition(l, r) {
        const pivotValue = state.array[r];
        state.pivotIndex = r;
        draw();
        await step();
        let i = l;
        for (let j = l; j < r; j++) {
            state.compareIndices = [j, state.pivotIndex];
            draw();
            await step();
            state.compareIndices = [];
            if (state.array[j] < pivotValue) {
                state.swapIndices = [i, j];
                draw();
                await step();
                swap(i, j);
                state.swapIndices = [];
                i++;
            }
            draw();
            await step();
        }
        state.swapIndices = [i, r];
        draw();
        await step();
        swap(i, r);
        state.swapIndices = [];
        state.pivotIndex = null;
        draw();
        await step();
        return i;
    }

    async function mergeSort(l = 0, r = state.array.length - 1) {
        state.stack.push({ l, r, type: 'merge' });
        if (l < r) {
            const m = Math.floor((l + r) / 2);
            await mergeSort(l, m);
            await mergeSort(m + 1, r);
            await merge(l, m, r);
        }
        state.stack.pop();
    }

    async function merge(l, m, r) {
        const left = state.array.slice(l, m + 1);
        const right = state.array.slice(m + 1, r + 1);
        let i = 0, j = 0, k = l;
        while (i < left.length && j < right.length) {
            state.compareIndices = [k];
            draw();
            await step();
            state.compareIndices = [];
            if (left[i] <= right[j]) {
                state.swapIndices = [k];
                state.array[k] = left[i++];
            } else {
                state.swapIndices = [k];
                state.array[k] = right[j++];
            }
            draw();
            await step();
            state.swapIndices = [];
            k++;
        }
        while (i < left.length) {
            state.array[k++] = left[i++];
        }
        while (j < right.length) {
            state.array[k++] = right[j++];
        }
        draw();
        await step();
    }

    async function heapSort() {
        const n = state.array.length;
        for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
            await heapify(n, i);
        }
        for (let i = n - 1; i > 0; i--) {
            swap(0, i);
            state.sortedCount = n - i;
            await step();
            await heapify(i, 0);
        }
        state.sortedCount = n;
        draw();
    }

    async function heapify(n, i) {
        let largest = i;
        const l = 2 * i + 1;
        const r = 2 * i + 2;
        if (l < n) {
            state.compareIndices = [l, largest];
            draw();
            await step();
            state.compareIndices = [];
            if (state.array[l] > state.array[largest]) largest = l;
        }
        if (r < n) {
            state.compareIndices = [r, largest];
            draw();
            await step();
            state.compareIndices = [];
            if (state.array[r] > state.array[largest]) largest = r;
        }
        if (largest !== i) {
            swap(i, largest);
            await step();
            await heapify(n, largest);
        }
    }

    async function radixSort() {
        const max = Math.max(...state.array);
        let exp = 1;
        while (Math.floor(max / exp) > 0) {
            await countingSort(exp);
            exp *= 10;
        }
        state.sortedCount = state.array.length;
        draw();
    }

    async function countingSort(exp) {
        const n = state.array.length;
        const output = new Array(n).fill(0);
        const count = Array(10).fill(0);
        for (let i = 0; i < n; i++) {
            const index = Math.floor(state.array[i] / exp) % 10;
            count[index]++;
        }
        for (let i = 1; i < 10; i++) count[i] += count[i - 1];
        for (let i = n - 1; i >= 0; i--) {
            const index = Math.floor(state.array[i] / exp) % 10;
            output[count[index] - 1] = state.array[i];
            count[index]--;
        }
        for (let i = 0; i < n; i++) {
            state.compareIndices = [i];
            draw();
            await step();
            state.compareIndices = [];
            state.array[i] = output[i];
        }
    }

    // Event listeners
    algorithmSelect.addEventListener('change', () => {
        state.algorithm = algorithmSelect.value;
        setComplexity();
    });

    startButton.addEventListener('click', async () => {
        if (state.isRunning) return;
        state.isRunning = true;
        state.comparisons = 0;
        state.swaps = 0;
        state.sortedCount = 0;
        state.stack = [];
        state.update = () => {
            state.comparisons++;
            updateStats();
        };
        let algoFunc;
        if (state.algorithm === 'bubblesort') algoFunc = bubbleSort;
        else if (state.algorithm === 'quicksort') algoFunc = quickSort;
        else if (state.algorithm === 'mergesort') algoFunc = mergeSort;
        else if (state.algorithm === 'heapsort') algoFunc = heapSort;
        else if (state.algorithm === 'radixsort') algoFunc = radixSort;
        await algoFunc();
        state.isRunning = false;
    });

    speedSlider.addEventListener('input', () => {
        state.speed = speedSlider.value;
        state.delay = 200 / state.speed;
    });

    continuousCheckbox.addEventListener('change', () => {
        state.continuous = continuousCheckbox.checked;
        nextButton.style.display = state.continuous ? 'none' : 'inline-block';
    });

    nextButton.addEventListener('click', () => {
        if (state.stepResolve) state.stepResolve();
    });

    scrambleButton.addEventListener('click', () => {
        if (state.isRunning) return;
        scrambleArray(scrambleSelect.value);
    });

    // Initialize
    scrambleArray('random');
    setComplexity();
    updateStats();
    draw();
});

